local factor=1.35
dragon.WingScale=factor
local function stretch(point,pivot)
    return {pivot[1]+(point[1]-pivot[1])*factor,pivot[2]+(point[2]-pivot[2])*factor,pivot[3]+(point[3]-pivot[3])*factor}
end
for _,group in ipairs({'LeftWing','RightWing'})do
    local pivot=dragon.Pivots[group]
    local bounds=dragon.Bounds[group]
    dragon.Bounds[group]={stretch(bounds[1],pivot),stretch(bounds[2],pivot)}
    for i,point in ipairs(dragon.FloorSamples[group])do dragon.FloorSamples[group][i]=stretch(point,pivot)end
    for _,part in ipairs(dragon.Parts)do if part.Group==group then
        part.Center=stretch(part.Center,pivot)
        part.Size={part.Size[1]*factor,part.Size[2]*factor,part.Size[3]*factor}
    end end
end
-- R38: only the three approved replacement stages use native biped rigs.
for stage,rig in pairs(require(script.Parent.KeeperUpgradeData))do Config[stage]=rig end
return Config
